async ({ workspace: { search, edit }, git: { tag } }) => {
  const tags = (await tag(["-l", "v0.3[4-7]*"])).stdout.trim().split("\n");
  const vs = ["0.37.1","0.37.0","0.36.6","0.36.5","0.36.4","0.36.3","0.36.2","0.36.1","0.36.0","0.35.1","0.35.0","0.34.0"];
  const missing = vs.filter((v) => !tags.includes(`v${v}`));
  if (missing.length) return { missing, tags };
  const lines = vs.slice(0, -1).map((v, i) => `[${v}]: https://github.com/cv/pit/compare/v${vs[i + 1]}...v${v}`);
  const s = await search("[0.38.0]: https://", { path: "CHANGELOG.md" });
  const m = s.matches[0];
  await edit("CHANGELOG.md", { revision: m.revision, changes: [{ kind: "insertAfter", anchor: m.anchor, content: lines.join("\n") }] });
  return { added: lines.length };
}
